/** Live orgs the user still holds a live membership in. Closed workspaces are omitted. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/** True when the workspace has been closed. A missing row is not closed. */
export async function isClosedWorkspace(orgId: OrgId): Promise<boolean> {
  const org = await findOrgById(orgId);
  return org !== null && org.archivedAt !== null;
}

/**
 * Refuses reads and writes against a closed workspace. A missing row is left
 * for the caller's own not-found check.
 */
export async function assertWorkspaceOpen(orgId: OrgId): Promise<void> {
  if (await isClosedWorkspace(orgId)) {
    throw new WorkspaceClosedError(orgId);
  }
}

