export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(and(eq(organizations.id, orgId), isNull(organizations.archivedAt)))
    .returning()
    .get();

  if (!row) {
    const existing = await findOrgById(orgId);
    if (existing && existing.archivedAt !== null) {
      throw new AlreadyArchivedError("Organization", orgId);
    }
    throw new Error(`Organization ${orgId} not found`);
  }
  return toOrganization(row);
}

/** Drops every delivery still waiting, so a closed workspace cannot send them later. */
export async function failPendingDeliveries(
  orgId: OrgId,
  error: string,
): Promise<void> {
  getDb()
    .update(webhookDeliveries)
    .set({
      status: "failed",
      lastError: error.slice(0, 500),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.status, "pending"),
      ),
    )
    .run();
}

