 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
90→  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
100→
  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  assertNotArchived("Organization", org.id, org);

  const archived = await orgRepo.archiveOrg(input.orgId);

  // The subscription ends at the moment of closing, so a later trial expiry
110→  // cannot record a plan change or leave the subscription active.
  const subscription = await subscriptionRepo.findSubscription(input.orgId);
  if (subscription) {
    await subscriptionRepo.cancelSubscription(
      input.orgId,
      toIsoTimestamp(new Date()),
    );
  }

  await webhookRepo.failPendingDeliveries(
120→    input.orgId,
    "workspace is closed",
  );
  await invitationRepo.revokePendingInvitations(input.orgId);

  return archived;
}

